"""Checks that a lit.site.cfg.py generated by expand_template is complete.

Fails if any @VAR@ placeholder from the CMake template was left unsubstituted
or if the result is not valid Python.
"""

import re
import sys

PLACEHOLDER = re.compile(r"@[A-Za-z_][A-Za-z0-9_]*@")


def main(argv):
    if len(argv) != 2:
        print("usage: %s <lit.site.cfg.py>" % argv[0], file=sys.stderr)
        return 2
    path = argv[1]
    with open(path) as f:
        source = f.read()

    errors = []
    for lineno, line in enumerate(source.splitlines(), start=1):
        for match in PLACEHOLDER.finditer(line):
            errors.append(
                "%s:%d: unsubstituted placeholder %s" % (path, lineno, match.group())
            )
    try:
        compile(source, path, "exec")
    except SyntaxError as e:
        errors.append("%s:%s: not valid Python: %s" % (path, e.lineno, e.msg))

    for error in errors:
        print(error, file=sys.stderr)
    if errors:
        print(
            "Add the missing variables to the lit_site_cfg_py substitutions in "
            "utils/bazel/llvm-project-overlay/mlir/test/BUILD.bazel.",
            file=sys.stderr,
        )
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
